import React from 'react';
import useReveal from './useReveal';

export default function Contact({ data }) {
  const { email, phone, location } = data.personal;
  const { ref, visible } = useReveal();

  return (
    <section
      id="contact"
      style={{ padding: '6rem 3rem', background: 'var(--bg)', textAlign: 'center' }}
    >
      <div ref={ref} style={{ opacity: visible ? 1 : 0, transform: visible ? 'none' : 'translateY(30px)', transition: 'all 0.7s' }}>
        <div style={{ fontFamily: 'var(--mono)', fontSize: 11, color: 'var(--accent)', letterSpacing: 4, marginBottom: '1rem' }}>
          06 / CONTACT
        </div>
        <h2 style={{
          fontSize: 'clamp(2.5rem, 6vw, 5rem)', fontWeight: 800,
          letterSpacing: -2, marginBottom: '1rem',
          background: 'linear-gradient(135deg, #fff, var(--accent) 60%, var(--accent2))',
          WebkitBackgroundClip: 'text', WebkitTextFillColor: 'transparent', backgroundClip: 'text',
        }}>
          Let's Build<br />Together.
        </h2>
        <p style={{ color: 'var(--muted)', fontFamily: 'var(--mono)', fontSize: 14, marginBottom: '3rem' }}>
          // Open to internships, freelance projects & collaborations
        </p>

        <div style={{ display: 'flex', justifyContent: 'center', flexWrap: 'wrap', gap: '1rem', marginBottom: '3rem' }}>
          <ContactLink href={`mailto:${email}`} label={`📧 ${email}`} />
          <ContactLink href={`tel:${phone}`} label={`📱 ${phone}`} />
          <ContactLink href="#" label={`📍 ${location}`} />
        </div>

        <a href={`mailto:${email}`} style={{
          padding: '0.9rem 2.5rem',
          background: 'var(--accent)', color: '#fff',
          border: 'none', borderRadius: 4,
          fontFamily: 'var(--mono)', fontSize: 14,
          letterSpacing: 1, cursor: 'pointer',
          display: 'inline-block', textDecoration: 'none',
        }}>
          Send a Message →
        </a>
      </div>
    </section>
  );
}

function ContactLink({ href, label }) {
  const [hovered, setHovered] = React.useState(false);
  return (
    <a
      href={href}
      onMouseEnter={() => setHovered(true)}
      onMouseLeave={() => setHovered(false)}
      style={{
        padding: '0.9rem 1.8rem',
        background: 'var(--card)',
        border: `1px solid ${hovered ? 'var(--accent)' : 'var(--border)'}`,
        borderRadius: 8,
        color: hovered ? 'var(--accent)' : 'var(--text)',
        fontFamily: 'var(--mono)', fontSize: 13,
        display: 'flex', alignItems: 'center', gap: '0.6rem',
        transform: hovered ? 'translateY(-3px)' : 'none',
        transition: 'all 0.3s', textDecoration: 'none',
      }}
    >
      {label}
    </a>
  );
}
